+    const int sState_addr = smem + 1024;
+    float* sQ = reinterpret_cast<float*>(smem_raw + 50176);
+    const int sQ_addr = smem + 50176;
+    float* sK = reinterpret_cast<float*>(smem_raw + 50688);
+    const int sK_addr = smem + 50688;
