+            } else {
+                v_0 = 1;
+            }
+        }
+        if (v_0 == 1) {
+            int other = home ^ 1;
+            int got_1 = 0;
+            int tiles_1 = items0;
+            if (other == 0) {
+                int _atomic_fetch_add_4 = atomicAdd(counters0, 1);
+                got_1 = _atomic_fetch_add_4;
+                if (got_1 == items0 + ctas - 1) {
+                    counters0[0] = 0;
+                }
+            } else {
+                tiles_1 = items1;
+                int _atomic_fetch_add_5 = atomicAdd(counters1, 1);
+                got_1 = _atomic_fetch_add_5;
+                if (got_1 == items1 + ctas - 1) {
