+        sword[0] = word;
+    }
+    __syncthreads();
+    int cur;
+    asm volatile("redux.sync.min.s32 %0, %1, 0xFFFFFFFF;" : "=r"(cur) : "r"(sword[0]));
+    if (cur != -1) {
+        int item = cur >> 1;
+        int row = item / HV;
