+    }
+    int cs = 0;
+    int trip = 1;
+    unsigned int _phase_full = 0;
+    while (cur != -1) {
+        int item_1 = cur >> 1;
+        int row_1 = item_1 / HV;
+        int head_1 = item_1 - row_1 * HV;
+        if ((cur & 1) == 1) {
+            row_1 = row_1 + rows0;
+        }
+        if (tid == 224) {
+            int v_1 = visit;
+            int word_1 = -1;
+            if (v_1 == 0) {
+                int got_2 = 0;
+                int tiles_2 = items0;
+                if (home == 0) {
+                    int _atomic_fetch_add_6 = atomicAdd(counters0, 1);
+                    got_2 = _atomic_fetch_add_6;
+                    if (got_2 == items0 + ctas - 1) {
