+                        mbarrier_arrive_expect_tx(full_addr + (((cs + 2 >= 3) ? cs + 2 - 3 : cs + 2)) * 8, 16384);
+                        tma_4d_gmem2smem(sState_addr + (unsigned int)(((cs + 2 >= 3) ? cs + 2 - 3 : cs + 2) * 16384), (&state_tma), (tile + 2) * 32, 0, head_1, row_1, full_addr + (((cs + 2 >= 3) ? cs + 2 - 3 : cs + 2)) * 8);
+                    }
+                }
