+                if (warp == 0) {
+                    if (elect_sync()) {
+                        asm volatile("cp.async.bulk.wait_group.read 0;");
+                        mbarrier_arrive_expect_tx(full_addr + (((cs + 2 >= 3) ? cs + 2 - 3 : cs + 2)) * 8, 16384);
