+// The 4D tensor map of the [B, HV, K=128, V=128] FP32 state the kernel reads and writes through TMA
+// (`const __grid_constant__ CUtensorMap state_tma`): dims innermost first (V, K, HV, B), byte strides of
+// K, HV and B, a 32 x 128 x 1 x 1 box (one 32-wide V panel of one state head), 128-byte swizzle, no L2
+// promotion, no out-of-bounds fill.  The state is contiguous (checked), so the strides follow the shape.
+// The map holds the state's device address and is passed by value as a kernel parameter.  A CUDA graph
+// captures the parameter bytes, so a replay addresses the pool the capture saw (as the pointer ABI
+// does); a new pool pointer needs a new capture.
+inline CUtensorMap EncodeStateTma4D(const TensorView& state) {
+  uint64_t global_dim[4] = {128u, 128u, (uint64_t)state.size(1), (uint64_t)state.size(0)};
+  uint64_t global_strides[3] = {128u * 4u, 128u * 128u * 4u, (uint64_t)state.size(1) * 128u * 128u * 4u};
+  uint32_t box_dim[4] = {32u, 128u, 1u, 1u};
+  uint32_t elem_strides[4] = {1u, 1u, 1u, 1u};
+  CUtensorMap tm{};
+  CUresult r = cuTensorMapEncodeTiled(
+      &tm, CU_TENSOR_MAP_DATA_TYPE_FLOAT32, 4, state.data_ptr(), global_dim, global_strides, box_dim,
+      elem_strides, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B,
+      CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
+  TVM_FFI_CHECK(r == CUDA_SUCCESS, RuntimeError)
+      << "cuTensorMapEncodeTiled (4D, 'state') failed: CUresult=" << (int)r;
+  return tm;
+}
+
+// The encoded map is a function of the state's base address, batch and head count alone (every other
+// argument of the encode is fixed above), so each host thread keeps the maps it encoded in a small
+// direct-mapped table keyed by (device, address, B, HV) and encodes only on a miss: a hit returns the
+// bytes the encode returned for the same key, so the launch, its output and a graph capture are the
+// same as with a fresh encode.  An entry never outlives its key: a different address, batch, head
+// count or device is a miss and overwrites the slot.
+struct StateTmaCacheEntry {
+  CUtensorMap map;
+  const void* data;
+  int64_t batch;
+  int64_t heads;
+  int device_id;
+  bool valid;
+};
+constexpr uint64_t kStateTmaCacheSlots = 64;
+
+inline CUtensorMap StateTma4D(const TensorView& state, int device_id) {
+  TVM_FFI_CHECK(reinterpret_cast<uintptr_t>(state.data_ptr()) % 16 == 0, ValueError)
+      << "state must be 16-byte aligned for the TMA state path";
+  thread_local StateTmaCacheEntry cache[kStateTmaCacheSlots] = {};
+  const void* data = state.data_ptr();
+  const int64_t batch = state.size(0);
+  const int64_t heads = state.size(1);
+  const uint64_t address = reinterpret_cast<uintptr_t>(data);
+  StateTmaCacheEntry& entry =
+      cache[((address >> 9) ^ (address >> 21) ^ (uint64_t)batch) % kStateTmaCacheSlots];
+  if (!(entry.valid && entry.data == data && entry.batch == batch && entry.heads == heads &&
+        entry.device_id == device_id)) {
+    entry.map = EncodeStateTma4D(state);
+    entry.data = data;
+    entry.batch = batch;
+    entry.heads = heads;
+    entry.device_id = device_id;
+    entry.valid = true;
+  }
+  return entry.map;
+}
+
+// The CTAs of the kernel resident on device `device_id` at once: its occupancy at 256 threads and
+// `smem_bytes` of dynamic shared memory (queried after the dynamic shared-memory opt-in, without
+// which the kernel fits no CTA) times the SM count.  Four CTAs per SM when the query fails or
+// reports none; the grid only sets how many CTAs claim the items, never the result.  Kept per device.
+inline int64_t ResidentCtas(tvm::ffi::CubinKernel& kernel, int device_id, int smem_bytes,
+                            int64_t* cache, int cache_len) {
+  TVM_FFI_CHECK(device_id >= 0 && device_id < cache_len, RuntimeError)
+      << "resident-CTA cache does not cover cuda:" << device_id;
+  if (cache[device_id] > 0) {
+    return cache[device_id];
+  }
+  int sm_count = 0;
+  cudaError_t error = cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device_id);
+  TVM_FFI_CHECK(error == cudaSuccess && sm_count > 0, RuntimeError)
+      << "querying the SM count failed for cuda:" << device_id << ": cudaError=" << (int)error;
+  int per_sm = 0;
+  CUfunction function = nullptr;
+  if (cuKernelGetFunction(&function, reinterpret_cast<CUkernel>(kernel.GetHandle())) != CUDA_SUCCESS ||
+      cuOccupancyMaxActiveBlocksPerMultiprocessor(&per_sm, function, 256, (size_t)smem_bytes) !=
+          CUDA_SUCCESS ||
+      per_sm <= 0) {
+    per_sm = 4;
+  }
+  cache[device_id] = (int64_t)per_sm * sm_count;
+  return cache[device_id];
+}
